sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    gs.info('go into CustodyBulkRest API');
    // implement resource here
    var body = request.body.data;
    gs.info('request.body.data: ' + JSON.stringify(body));
    var action_type = body.action_type;
    gs.info('action_type: ' + action_type);

    var sysparm_outcome = body.sysparm_outcome;
    gs.info('sysparm_outcome: ' + sysparm_outcome);

    var sysparm_name = body.sysparm_name;
    gs.info('sysparm_name: ' + sysparm_name);

    var sysparm_query = body.sysparm_query;
    gs.info('sysparm_query: ' + sysparm_query);

    var sysparm_taskcount = body.sysparm_taskcount;
    gs.info('sysparm_taskcount: ' + sysparm_taskcount);

    var sysparm_bulkOptionField = body.sysparm_bulkOptionField;
    gs.info('sysparm_bulkOptionField: ' + sysparm_bulkOptionField);

    var traderec = body.traderec;
    gs.info('traderec: ' + traderec);

    var sysparm_filter = body.sysparm_filter;
    gs.info('sysparm_filter: ' + sysparm_filter);

    var user_id = gs.getUserID();
    gs.info('getUserID: ' + gs.getUserID());


    var bulk_trade_util = new MSSCustodyBulkTradeUtils_workspace();
    var bulk_task_util = new MSSCustodyBulkUtils_workspace();
    var bulk_proc_util = new MSSCustodyBulkProcessUtils_workspace();
    var bulk_Id;

    // Create bulk for selected
    if (action_type === 'selected' && sysparm_name === 'createTradeBulkIDUpdated') {
        bulk_Id = bulk_trade_util.createTradeBulkIDUpdated(sysparm_outcome, sysparm_query, sysparm_taskcount, sysparm_filter, user_id);
        //var bulk_Id = '12345678';
        gs.info('bulk_Id: ' + bulk_Id);
        bulk_trade_util.linkBulkWithCaseTask(sysparm_outcome, sysparm_query, bulk_Id);
        response.setStatus(201);
        return {
            "message": "Create bulk for selected - " + sysparm_outcome,
            "bulk_Id": bulk_Id
        };
    }
    // Create bulk for filtered
    else if (action_type === 'filtered' && sysparm_name === 'createTradeBulkIDUpdated') {
        bulk_Id = bulk_trade_util.createTradeBulkIDUpdated(sysparm_outcome, sysparm_query, sysparm_taskcount, sysparm_filter, user_id);
        //var bulk_Id = '12345678';
        gs.info('bulk_Id: ' + bulk_Id);
        //bulk_trade_util.linkBulkWithCaseTask(sysparm_outcome, sysparm_query, bulk_Id);
        //bulk_proc_util.createBulkCaseTask(sysparm_query, bulk_Id, sysparm_outcome, sysparm_taskcount);
        var parm1 = JSON.stringify({
            query: sysparm_query,
            bulkId: bulk_Id,
            outcome: sysparm_outcome,
            taskCount: sysparm_taskcount,
            userId: user_id
        });
        //var parm1 = 'aaa';
        gs.eventQueue('x_hsb11_mss_c_proc.bulk.case.task.create', current, parm1);
        response.setStatus(201);
        return {
            "message": "Create bulk for filtered  - " + sysparm_outcome,
            "bulk_Id": bulk_Id
        };
    }
    // Create bulk for selected - for custody task
    else if (action_type === 'selected task' && sysparm_outcome === 'Create Bulk for Selected') {
        gs.info('sysparm_query: ' + sysparm_query);
        gs.info('sysparm_taskcount: ' + sysparm_taskcount);
        bulk_Id = String(bulk_task_util.createAutomatedTaskBulkID(sysparm_query, sysparm_taskcount));
        gs.info('bulk_Id: ' + bulk_Id);
        response.setStatus(201);
        return {
            "message": "Create bulk for selected task",
            "bulk_Id": bulk_Id
        };
    }
    // Create bulk for filtered - for custody task
    else if (action_type === 'filtered task' && sysparm_outcome === 'Create Bulk for All Filtered') {
        bulk_Id = String(bulk_task_util.createAutomatedTaskBulkID(sysparm_query, sysparm_taskcount));
        //var bulk_Id = '12345678';
        gs.info('bulk_Id: ' + bulk_Id);
        response.setStatus(201);
        return {
            "message": "Create bulk for filtered task",
            "bulk_Id": bulk_Id
        };
    }
    // evalbulk for custody task
    else if (sysparm_name === 'evalBulkOptionTaskList') {
        var enableBulkOptionTask = bulk_task_util.evalBulkOptionTaskList(sysparm_query);
        gs.info('evalBulkOptionTaskList: ' + enableBulkOptionTask);
        response.setStatus(201);
        return {
            "message": "Call evalBulk function for task",
            "enableBulkOptionTask": enableBulkOptionTask
        };
    }
    // evalBulk - for custody trade
    else if (action_type === 'selected_evalBulk' || action_type === 'filtered_evalBulk') {
        var enableBulkOption = bulk_trade_util.bulkUnavailableUserInformation(sysparm_query, user_id);
        gs.info('enableBulkOption=' + enableBulkOption);
        response.setStatus(201);
        return {
            "message": "Call evalBulk function",
            "enableBulkOption": enableBulkOption,
        };
    }
    // evalBulk - handleSingleFilteredCheck for custody trade
    else if (sysparm_name === 'bulkUnavailabilityforSingleFiltered') {
        var row_count = bulk_trade_util.bulkUnavailabilityforSingleFiltered(sysparm_query);
        gs.info('row_count=' + row_count);
        response.setStatus(201);
        return {
            "message": "Call evalBulk function",
            "row_count": row_count,
        };
    }
    // evalTrade - for custody trade
    else if (sysparm_bulkOptionField) {
        //gs.info('go to selected_evalTrade: ' + sysparm_bulkOptionField);
        var enableTradeOption = bulk_trade_util.evalBulkOptionTradeList(sysparm_query, sysparm_bulkOptionField, user_id);
        //gs.info('selected_evalTrade enableTradeOption=' + enableTradeOption);
        response.setStatus(201);
        return {
            "message": "Call evalTrade function",
            "enableTradeOption": enableTradeOption,
        };
    }
    // associateTrade for WIMT
    else if (traderec && sysparm_name === 'retrieveCBR') {
        var answer = bulk_trade_util.retrieveCBR(traderec);
        var returnVal = JSON.parse(answer);
        var cVal = returnVal.cbrValue;
        var count = returnVal.count;
        gs.info('cVal ' + cVal);
        gs.info('count ' + count);

        response.setStatus(201);
        return {
            "message": "Call associateTrade function",
            "cVal": cVal,
            "count": count
        };
    } else {
        return {
            "message": "NO action selected!",
            "bulk_Id": "No bulk_id or enableBulkOption returned!"
        };
    }
})(request, response);
